import { test, expect } from '@playwright/test';

test.describe('Multi-Step Form - Back Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/multi-step-form');
  });

  test('should navigate back to previous step without losing data', async ({ page }) => {
    // Fill out Step 1
    const step1Input = page.getByLabel('Full Name');
    await step1Input.fill('John Doe');

    const step1SubmitButton = page.getByRole('button', { name: /submit/i });
    await step1SubmitButton.click();

    // Verify Step 2 is displayed
    const step2Title = page.getByRole('heading', { name: /step 2/i });
    await expect(step2Title).toBeVisible();

    // Fill out Step 2
    const step2EmailInput = page.getByLabel('Email Address');
    await step2EmailInput.fill('john.doe@example.com');

    const step2SubmitButton = page.getByRole('button', { name: /submit/i });
    await step2SubmitButton.click();

    // Verify Step 3 is displayed
    const step3Title = page.getByRole('heading', { name: /step 3/i });
    await expect(step3Title).toBeVisible();

    // Navigate back to Step 2
    const backButton = page.getByRole('button', { name: /back/i });
    await backButton.click();

    // Verify Step 2 is still visible
    await expect(step2Title).toBeVisible();

    // Verify data is preserved
    await expect(step2EmailInput).toHaveValue('john.doe@example.com');

    // Navigate back to Step 1
    await backButton.click();

    // Verify Step 1 is visible
    await expect(step1Title).toBeVisible();

    // Verify data is preserved
    await expect(step1Input).toHaveValue('John Doe');
  });

  test('should handle navigation to a non-existent step', async ({ page }) => {
    // Fill out Step 1
    const step1Input = page.getByLabel('Full Name');
    await step1Input.fill('Jane Smith');

    const step1SubmitButton = page.getByRole('button', { name: /submit/i });
    await step1SubmitButton.click();

    // Verify Step 2 is displayed
    const step2Title = page.getByRole('heading', { name: /step 2/i });
    await expect(step2Title).toBeVisible();

    // Navigate to a non-existent step (Step 5)
    const nonExistentStepButton = page.getByRole('button', { name: /back/i });
    await nonExistentStepButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText(/step does not exist/i);
    await expect(errorMessage).toBeVisible();

    // Verify navigation is still possible to Step 2
    const step2BackButton = page.getByRole('button', { name: /back/i });
    await step2BackButton.click();

    // Verify Step 2 is visible
    await expect(step2Title).toBeVisible();
  });
});
